// utils/flyweight/{flyweight}/{Flyweight}Registry.ts
// Flyweight — partage l'état intrinsèque entre toutes les instances

// État intrinsèque — partagé, immuable, jamais muté
interface {Flyweight}IntrinsicState {
  // Ajoute ici les propriétés partagées (identiques pour toutes les instances)
  // Exemple : name, color, size, ariaLabel
}

// Flyweight — objet léger avec état intrinsèque uniquement
class {Flyweight}Flyweight {
  // L'état intrinsèque est readonly — JAMAIS muté
  constructor(private readonly state: Readonly<{Flyweight}IntrinsicState>) {}

  // État extrinsèque passé au moment de l'utilisation — jamais stocké
  render(extrinsicState?: Record<string, unknown>): Record<string, unknown> {
    return {
      ...this.state,
      ...(extrinsicState ?? {})
    }
  }
}

// Fabrique Flyweight — gère le pool d'instances partagées
class {Flyweight}Registry {
  private pool = new Map<string, {Flyweight}Flyweight>()

  getOrCreate(key: string, state: {Flyweight}IntrinsicState): {Flyweight}Flyweight {
    if (!this.pool.has(key)) {
      this.pool.set(key, new {Flyweight}Flyweight(state))
    }
    return this.pool.get(key)!
  }

  get poolSize(): number {
    return this.pool.size
  }
}

// Instance unique du registry (Singleton + Flyweight)
const registry = new {Flyweight}Registry()

// Pré-enregistrement des instances partagées — créées une seule fois
// Ajoute ici tes instances partagées :
export const {FLYWEIGHT}_INSTANCES = {
  // Exemple :
  // default: registry.getOrCreate('default', { ... })
} as const

export { registry as {flyweight}Registry }

// utils/flyweight/{flyweight}/{Flyweight}Factory.ts
// Factory pour les instances avec état extrinsèque (paramètres variables)

type ValidationRule = (value: unknown) => true | string

// Les règles de base sont des Flyweights — créées une seule fois
// L'état extrinsèque (paramètres) est passé à la factory, pas stocké
export const create{Flyweight}Rules = {
  // Règles sans paramètre — pures Flyweights partagées
  required: (() => {
    const rule: ValidationRule = (v) => !!v || 'Champ obligatoire'
    return () => rule  // Retourne toujours la même fonction
  })(),

  // Règles paramétrées — l'état extrinsèque est le paramètre
  // La règle de base est partagée, seul le paramètre varie
  minLength: (min: number): ValidationRule =>
    (v) => String(v ?? '').length >= min || `Minimum ${min} caractères`,

  maxLength: (max: number): ValidationRule =>
    (v) => String(v ?? '').length <= max || `Maximum ${max} caractères`,

  min: (min: number): ValidationRule =>
    (v) => Number(v) >= min || `Valeur minimum : ${min}`,

  max: (max: number): ValidationRule =>
    (v) => Number(v) <= max || `Valeur maximum : ${max}`,

  // Ajoute ici tes règles spécifiques au projet
}

// tests/utils/flyweight/{flyweight}/{Flyweight}Registry.spec.ts
import { describe, it, expect } from 'vitest'
import { {flyweight}Registry } from '~/utils/flyweight/{flyweight}/{Flyweight}Registry'
import { create{Flyweight}Rules } from '~/utils/flyweight/{flyweight}/{Flyweight}Factory'

describe('{Flyweight}Registry', () => {

  it('getOrCreate() retourne la même instance pour la même clé', () => {
    const state = { /* Ajoute ici un état exemple */ }
    const a = {flyweight}Registry.getOrCreate('test', state as any)
    const b = {flyweight}Registry.getOrCreate('test', state as any)
    expect(a).toBe(b)  // Même référence — objet partagé
  })

  it('getOrCreate() crée une nouvelle instance pour une clé différente', () => {
    const state = { /* Ajoute ici un état exemple */ }
    const a = {flyweight}Registry.getOrCreate('key-a', state as any)
    const b = {flyweight}Registry.getOrCreate('key-b', state as any)
    expect(a).not.toBe(b)
  })

  it('poolSize augmente uniquement pour les nouvelles clés', () => {
    const before = {flyweight}Registry.poolSize
    const state  = { /* état exemple */ }
    {flyweight}Registry.getOrCreate(`unique-${Date.now()}`, state as any)
    expect({flyweight}Registry.poolSize).toBe(before + 1)
  })

})

describe('create{Flyweight}Rules', () => {

  it('required() retourne true pour une valeur non vide', () => {
    expect(create{Flyweight}Rules.required()('valeur')).toBe(true)
  })

  it('required() retourne un message d\'erreur pour une valeur vide', () => {
    expect(create{Flyweight}Rules.required()('')).not.toBe(true)
  })

  it('minLength() retourne true si la valeur est assez longue', () => {
    expect(create{Flyweight}Rules.minLength(3)('abc')).toBe(true)
  })

  it('minLength() retourne un message si trop court', () => {
    expect(create{Flyweight}Rules.minLength(5)('ab')).not.toBe(true)
  })

  it('maxLength() retourne true si la valeur est assez courte', () => {
    expect(create{Flyweight}Rules.maxLength(10)('court')).toBe(true)
  })

  it('required() retourne toujours la même référence de fonction', () => {
    // Vérifie le partage — même règle, même référence
    const r1 = create{Flyweight}Rules.required()
    const r2 = create{Flyweight}Rules.required()
    expect(r1).toBe(r2)
  })

})
